Set-Location 'D:\Svemir\!Projekti\Beops'
$py='C:\Svemir\python.cmd'
& $py -B tools/legal_capture.py --sid S143 --name 'Pleiades - gazetteer of the ancient world' --url 'https://pleiades.stoa.org/' --note 'named opt-out' --refused 'robots.txt names anthropic-ai, ClaudeBot and Claude-Web with Disallow: / . User-agent: * permits everything, so a collector under any other name reads as allowed - which is circumvention by choice of name. Refused by decision, and the site also serves an Anubis anti-AI proof-of-work challenge.' 2>&1 | Select-String 'allowed_for_us|manual_' | Select-Object -First 5
& $py -B tools/legal_capture.py --sid S141 --name 'Wikidata Query Service' --url 'https://query.wikidata.org/sparql' --terms 'https://www.wikidata.org/wiki/Wikidata:Licensing' --note 'keyless SPARQL, CC0 content' --needs-decision 'robots.txt at query.wikidata.org disallows /sparql for User-agent: *. The evident target is search crawlers following expensive query links, not API clients using an endpoint built to be queried programmatically. Letter and intent diverge - EDGE_CASES.md E-009.' 2>&1 | Select-String 'allowed_for_us|manual_' | Select-Object -First 5
& $py -B tools/legal_capture.py --sid S142 --name 'Overpass API' --url 'https://overpass-api.de/api/status' --terms 'https://www.openstreetmap.org/copyright' --note 'keyless, ODbL' --needs-decision 'robots.txt at overpass-api.de disallows /api/ for User-agent: *, while publishing a sitemap under that same path. Same shape as Wikidata - EDGE_CASES.md E-009.' 2>&1 | Select-String 'allowed_for_us|manual_' | Select-Object -First 5
& $py -B tools/build_provenance_index.py
